// Simple asteroid‑shower game
// Canvas with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // safety
  const ctx = canvas.getContext('2d');
  const { width, height } = canvas;

  // ----- game objects -----
  const ship = { x: width / 2, y: height - 30, w: 40, h: 20, speed: 5 };
  const lasers = [];
  const asteroids = [];
  let left = false, right = false, fire = false;
  let gameOver = false;

  // ----- input handling -----
  document.addEventListener('keydown', e => {
    if (e.code === 'ArrowLeft') left = true;
    if (e.code === 'ArrowRight') right = true;
    if (e.code === 'Space') fire = true;
  });
  document.addEventListener('keyup', e => {
    if (e.code === 'ArrowLeft') left = false;
    if (e.code === 'ArrowRight') right = false;
    if (e.code === 'Space') fire = false;
  });

  // ----- helpers -----
  const rectCollide = (a, b) =>
    a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;

  const spawnAsteroid = () => {
    const size = 20 + Math.random() * 30;
    const x = Math.random() * (width - size);
    const speed = 1 + Math.random() * 2;
    asteroids.push({ x, y: -size, w: size, h: size, speed });
  };

  // ----- main loop -----
  let lastSpawn = 0;
  function update(dt) {
    if (gameOver) return;

    // ship movement
    if (left) ship.x -= ship.speed;
    if (right) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(width - ship.w, ship.x));

    // fire lasers
    if (fire) {
      // limit fire rate
      if (!ship.lastShot || Date.now() - ship.lastShot > 200) {
        lasers.push({ x: ship.x + ship.w / 2 - 2, y: ship.y, w: 4, h: 10, speed: 7 });
        ship.lastShot = Date.now();
      }
    }

    // update lasers
    lasers.forEach(l => l.y -= l.speed);
    // remove off‑screen lasers
    for (let i = lasers.length - 1; i >= 0; i--) {
      if (lasers[i].y + lasers[i].h < 0) lasers.splice(i, 1);
    }

    // spawn asteroids every 1‑1.5 s
    if (Date.now() - lastSpawn > 1000 + Math.random() * 500) {
      spawnAsteroid();
      lastSpawn = Date.now();
    }

    // update asteroids
    asteroids.forEach(a => a.y += a.speed);

    // collisions: laser‑asteroid
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      // asteroid hits ship?
      if (rectCollide(a, ship)) { gameOver = true; break; }
      // asteroid reaches bottom?
      if (a.y > height) { gameOver = true; break; }
      for (let j = lasers.length - 1; j >= 0; j--) {
        if (rectCollide(a, lasers[j])) {
          asteroids.splice(i, 1);
          lasers.splice(j, 1);
          break;
        }
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // ship
    ctx.fillStyle = '#0af';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // lasers
    ctx.fillStyle = '#f00';
    lasers.forEach(l => ctx.fillRect(l.x, l.y, l.w, l.h));
    // asteroids
    ctx.fillStyle = '#777';
    asteroids.forEach(a => ctx.beginPath(), ctx.arc(a.x + a.w/2, a.y + a.h/2, a.w/2, 0, Math.PI*2), ctx.fill());
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0,0,width,height);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width/2, height/2);
    }
  }

  let last = 0;
  function loop(timestamp) {
    const dt = timestamp - last;
    last = timestamp;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
